package me.danialisntcool.factionfriction.faction;import java.util.*;public class OperationData {public UUID id=UUID.randomUUID(),attackerFactionId,defenderFactionId;public boolean raid;public int prepTimeRemaining;public State state=State.ACTIVE;public final List<OperationAttack> attacks=new ArrayList<>();public final Set<UUID> approvedSupportFactions=new HashSet<>();public final Map<UUID,Long> attackerAssignments=new HashMap<>(),defenderAssignments=new HashMap<>(),supporterAssignments=new HashMap<>();public OperationAttack getAttack(long p){return attacks.stream().filter(a->a.chunkLong()==p).findFirst().orElse(null);}public enum State {DRAFT,PREPARING,ACTIVE,ABORTING,COMPLETED}}